// Yahboom's aluminium alloy chassis as its two-wheel drive kit builds it: the two plates with the two motors under
// the rear, on the kit's two rubber wheels and the two casters under the nose.
Robot alloy_chassis_2wd {
    intent "Yahboom aluminium alloy chassis kit, two-wheel differential drive with two casters"

    Diff_two_caster chassis(ref = "yahboom_alloy_chassis_2wd")

    // The kit's motors, each on its bracket at a wheel.
    Motor motor_left(ref = "yahboom_l_type_520_encoder_motor", glue = (0, 0.0304, -0.06867, 0, 1, 0))
    Motor motor_right(ref = "yahboom_l_type_520_encoder_motor", glue = (0, -0.0304, -0.06867, 0, -1, 0))

    Standard wheel_left(ref = "yahboom_alloy_chassis_2wd_wheel", glue = (0, 0.06015, -0.0687, 0, 1, 0))
    Standard wheel_right(ref = "yahboom_alloy_chassis_2wd_wheel", glue = (0, -0.06015, -0.0687, 0, -1, 0))
}

